from collections import defaultdict
agg=defaultdict(lambda:[0,0,0,0])
for r in rows:
    g=agg[r["area"]]; g[3]+=1
    if r["points"] is not None: g[0]+=r["weight"]*r["points"]; g[1]+=r["weight"]; g[2]+=1
tot=wt=0
for a,w,_ in areas:
    e,k,n,t=agg[a]; sc=round(100*e/k); tot+=sc*w; wt+=w
    print(f"{a:32s} {sc:3d}  {n}/{t}")
print("overall", round(tot/wt,1), "checks", len(rows), "evidenced", sum(r['points'] is not None for r in rows))
